import React,{createContext,useContext,useEffect,useState} from 'react';
import{createRoot}from'react-dom/client';
import{BrowserRouter,NavLink,Route,Routes,useNavigate,useLocation}from'react-router-dom';
import{LayoutDashboard,Users,Building2,UserRound,KanbanSquare,CalendarDays,CheckSquare,FileText,Receipt,Wallet,LifeBuoy,ChartNoAxesCombined,Settings,UsersRound,Shield,SlidersHorizontal,Search,Bell,Plus,LogOut,PanelLeftClose,PanelLeftOpen,Menu,ChevronRight,LoaderCircle,AlertCircle,Check,ArrowRightLeft}from'lucide-react';
import{api,getCsrf,query}from'./api.js';
import'./styles.css';
import'./admin.css';
import'./theme-aurora.css';

const Session=createContext(null);const useSession=()=>useContext(Session);
const menu=[['Overview',[['Dashboard','/',LayoutDashboard]]],['CRM',[['Leads','/leads',Users],['Deals / Pipeline','/deals',KanbanSquare],['Contacts','/contacts',UserRound],['Accounts','/accounts',Building2]]],['Work',[['Activities','/activities',CheckSquare],['Calendar','/calendar',CalendarDays]]],['Finance',[['Quotes','/quotes',FileText],['Invoices','/invoices',Receipt],['Payments','/payments',Wallet]]],['Service',[['Support','/support',LifeBuoy]]],['Insights',[['Reports','/reports',ChartNoAxesCombined]]],['Administration',[['Settings','/settings',Settings],['Users','/users',UsersRound],['Teams','/teams',UsersRound],['Roles & Permissions','/roles',Shield],['Custom Fields','/custom-fields',SlidersHorizontal]]]];
const MENU_PERMISSION={'/':'dashboard.view','/leads':'leads.view','/deals':'deals.view','/contacts':'contacts.view','/accounts':'contacts.view','/activities':'activities.view','/calendar':'activities.view','/quotes':'billing.view','/invoices':'billing.view','/payments':'billing.view','/support':'tickets.view','/reports':'reports.view','/settings':'settings.view','/users':'users.view','/teams':'users.view','/roles':'users.manage','/custom-fields':'settings.view'};
const QUICK_PERMISSION={'/leads':'leads.manage','/deals':'deals.manage','/contacts':'contacts.manage','/activities':'activities.manage','/quotes':'billing.manage'};
const QUICK_ITEMS=[['Lead','/leads'],['Deal','/deals'],['Contact','/contacts'],['Task','/activities'],['Quote','/quotes']];
// Admin sees everything. If the API sent no permission list (older backend) nothing is hidden.
const can=(user,key)=>!key||user?.role==='Admin'||!Array.isArray(user?.permissions)||user.permissions.includes(key);
const visibleMenu=user=>menu.map(([group,items])=>[group,items.filter(([,path])=>can(user,MENU_PERMISSION[path]))]).filter(([,items])=>items.length>0);
const visibleQuick=user=>QUICK_ITEMS.filter(([,path])=>can(user,QUICK_PERMISSION[path]));
function App(){const [user,setUser]=useState(null),[loading,setLoading]=useState(true);useEffect(()=>{getCsrf().then(()=>api('auth/session')).then(s=>setUser(s.user)).catch(()=>{}).finally(()=>setLoading(false));},[]);if(loading)return <div className="splash"><LoaderCircle className="spin"/> Loading HA CRM</div>;return <Session.Provider value={{user,setUser}}><BrowserRouter basename={window.HA_CRM_BASE||undefined}>{user?<Shell/>:<AuthPage/>}</BrowserRouter></Session.Provider>}
function AuthPage(){
  const{setUser}=useSession(),[register,setRegister]=useState(false),[form,setForm]=useState({email:'',tenant_slug:'',password:'',tenant_name:'',full_name:'',password_confirmation:''}),[error,setError]=useState(''),[busy,setBusy]=useState(false);
  const change=e=>setForm({...form,[e.target.name]:e.target.value});
  async function submit(e){
    e.preventDefault();setError('');
    if(register&&form.password!==form.password_confirmation){setError('Passwords do not match.');return;}
    setBusy(true);
    try{
      await getCsrf();
      const body=register?{tenant_name:form.tenant_name,tenant_slug:form.tenant_slug,full_name:form.full_name,email:form.email,password:form.password,password_confirmation:form.password_confirmation,timezone:Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC'}:{email:form.email,tenant:form.tenant_slug,password:form.password};
      const result=await api(register?'auth/register':'auth/login',{method:'POST',body});setUser(result.user);
    }catch(e){setError(e.message)}finally{setBusy(false);}
  }
  function switchMode(){setRegister(!register);setError('');setForm({...form,password:'',password_confirmation:''});}
  return <main className="auth-wrap"><div className="auth-card"><div className="brand-mark">HA</div><h1>{register?'Set up workspace':'Welcome back'}</h1><p>{register?'Create a company workspace and its first administrator.':'Sign in to your HA CRM workspace.'}</p><form onSubmit={submit}>
    {register&&<><Field label="Workspace / Company name" name="tenant_name" value={form.tenant_name} onChange={change} required maxLength={150}/><Field label="Workspace slug" name="tenant_slug" value={form.tenant_slug} onChange={change} required minLength={3} maxLength={100} pattern="[a-zA-Z0-9]+(-[a-zA-Z0-9]+)*" title="Use letters and numbers with optional internal hyphens." autoCapitalize="none"/><Field label="Admin full name" name="full_name" value={form.full_name} onChange={change} required maxLength={100}/></>}
    <Field label="Email" name="email" type="email" value={form.email} onChange={change} required maxLength={190} autoComplete="email"/>
    {!register&&<Field label="Workspace Slug" name="tenant_slug" value={form.tenant_slug} onChange={change} required autoCapitalize="none"/>}
    <Field label="Password" name="password" type="password" value={form.password} onChange={change} required minLength={register?12:1} maxLength={register?72:undefined} autoComplete={register?'new-password':'current-password'}/>
    {register&&<Field label="Password confirmation" name="password_confirmation" type="password" value={form.password_confirmation} onChange={change} required minLength={12} maxLength={72} autoComplete="new-password"/>}
    {error&&<div className="error-line" role="alert"><AlertCircle size={16}/>{error}</div>}
    <button className="primary full" disabled={busy}>{busy?'Please wait…':register?'Create workspace':'Sign in'}</button>
  </form><button type="button" className="link-button" onClick={switchMode}>{register?'Already have a workspace? Sign in':'First time? Set up workspace'}</button></div></main>
}
function Shell(){const{user,setUser}=useSession(),[collapsed,setCollapsed]=useState(false),[drawer,setDrawer]=useState(null),[search,setSearch]=useState(''),[notifications,setNotifications]=useState([]),[quick,setQuick]=useState(false),[activeTasks,setActiveTasks]=useState(0),[searchResults,setSearchResults]=useState(null);const nav=useNavigate(),loc=useLocation();useEffect(()=>{let since=0,initial=true;const poll=()=>api(`notifications/poll?since=${since}`).then(rows=>{if(rows.length){since=rows.at(-1).id;setNotifications(n=>[...rows,...n].slice(0,30));if(!initial&&window.Notification?.permission==="granted")for(const n of rows)new window.Notification(n.title,{body:n.body||""});}initial=false;}).catch(()=>{});poll();const timer=setInterval(poll,20000);return()=>clearInterval(timer)},[]);useEffect(()=>{api('activities?status=Pending&per_page=100').then(v=>setActiveTasks(v.pagination?.total||0)).catch(()=>{})},[loc.pathname]);useEffect(()=>{setDrawer(null)},[loc.pathname]);async function logout(){try{await api('auth/logout',{method:'POST'});}finally{setUser(null)}}return <div className={`app-shell ${collapsed?'is-collapsed':''}`}><aside className="sidebar"><div className="brand"><span className="brand-mark small">HA</span>{!collapsed&&<span>HA <b>CRM</b></span>}<button className="icon-button collapse" onClick={()=>setCollapsed(!collapsed)} title="Collapse navigation">{collapsed?<PanelLeftOpen size={18}/>:<PanelLeftClose size={18}/>}</button></div><div className="nav-groups">{visibleMenu(user).map(([group,items])=><section key={group}><div className="nav-heading">{!collapsed&&group}</div>{items.map(([label,path,Icon])=><NavLink end={path==='/'} key={path} to={path} title={collapsed?label:undefined} className={({isActive})=>`nav-link ${isActive?'active':''}`}><Icon size={18}/>{!collapsed&&<span>{label}</span>}</NavLink>)}</section>)}</div><div className="sidebar-user"><div className="avatar">{user.full_name?.slice(0,1).toUpperCase()}</div>{!collapsed&&<div><strong>{user.full_name}</strong><small>{user.role}</small></div>}</div></aside><main className="main-area"><header className="topbar"><button className="icon-button mobile-menu" onClick={()=>setCollapsed(!collapsed)}><Menu size={20}/></button><div className="searchbox"><Search size={17}/><input placeholder="Search leads, deals, contacts…" value={search} onChange={e=>setSearch(e.target.value)} onKeyDown={async e=>{if(e.key==='Enter')try{setSearchResults(await api(`search?q=${encodeURIComponent(search)}`))}catch{setSearchResults([])}}} onBlur={()=>setTimeout(()=>setSearchResults(null),250)}/><kbd>↵</kbd></div>{searchResults&&<div className="search-results">{searchResults.length?searchResults.map((hit,i)=><button key={i} onMouseDown={e=>e.preventDefault()} onClick={()=>{nav({lead:'/leads',deal:'/deals',contact:'/contacts'}[hit.type]);setDrawer({type:'record',resource:hit.type==='lead'?'leads':hit.type==='deal'?'deals':'contacts',row:hit});setSearchResults(null)}}><strong>{hit.label}</strong><small>{hit.type} · {hit.detail}</small></button>):<span>No matches in your accessible records.</span>}</div>}<div className="top-actions">{visibleQuick(user).length>0&&<button className="primary quick" onClick={()=>setQuick(!quick)}><Plus size={17}/> Add New</button>}{quick&&<div className="quick-menu">{visibleQuick(user).map(([x,p])=><button key={x} onClick={()=>{nav(p);setQuick(false)}}>{x}</button>)}</div>}<button className="icon-button notification-button" title="Notifications" onClick={()=>setDrawer({type:'notifications'})}><Bell size={19}/>{notifications.length>0&&<i/>}</button><div className="task-pill"><CheckSquare size={15}/><span>{activeTasks}</span></div><button className="profile-button" onClick={logout}><span className="avatar tiny">{user.full_name?.slice(0,1).toUpperCase()}</span><span className="profile-name">{user.full_name}</span><LogOut size={15}/></button></div></header><div className="page-area"><Routes><Route path="/" element={<Dashboard/>}/><Route path="/deals" element={<Deals onOpen={setDrawer}/>}/><Route path="/calendar" element={<Calendar/>}/><Route path="/reports" element={<Reports/>}/><Route path="/settings" element={<SettingsPage/>}/>{['leads','contacts','accounts','activities','quotes','invoices','payments','support','users','teams','roles','custom-fields'].map(key=><Route key={key} path={`/${key}`} element={<ResourcePage resource={key} onOpen={setDrawer}/>}/>)}<Route path="*" element={<NotFound/>}/></Routes></div>{drawer&&<ContextDrawer value={drawer} close={()=>setDrawer(null)}/>}</main></div>}
function PageHeading({eyebrow,title,subtitle,action}){return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1>{subtitle&&<p>{subtitle}</p>}</div>{action}</div>}
function Dashboard(){const{user}=useSession(),[data,setData]=useState(null),[error,setError]=useState('');useEffect(()=>{api('dashboard').then(setData).catch(e=>setError(e.message))},[]);return <><PageHeading eyebrow="OVERVIEW" title={`Good ${new Date().getHours()<12?'morning':new Date().getHours()<18?'afternoon':'evening'}, ${user.full_name.split(' ')[0]}`} subtitle="Here’s what’s happening across your workspace today."/><ErrorBanner error={error}/>{!data?<Loading/>:<><div className="metric-grid"><Metric label="Total leads" value={data.leads.total} hint={`${data.leads.new_today} added today`} icon={Users}/><Metric label="Qualified rate" value={`${data.leads.qualified_rate}%`} hint="Qualified leads" icon={Check}/><Metric label="Unassigned" value={data.leads.unassigned} hint="Needs an owner" icon={UserRound}/><Metric label="Active stages" value={data.pipeline.length} hint="Pipeline columns" icon={KanbanSquare}/></div><div className="content-grid"><section className="panel"><div className="panel-head"><div><h2>Pipeline overview</h2><p>Deal volume by stage</p></div><button className="subtle-button" onClick={()=>location.assign(`${window.HA_CRM_BASE||''}/deals`)}>Open pipeline <ArrowRightLeft size={15}/></button></div><div className="stage-list">{data.pipeline.map(s=><div className="stage-row" key={s.id}><div className="stage-label"><span>{s.name}</span><small>{s.deal_count} deals</small></div><div className="bar"><i style={{width:`${Math.min(100,Number(s.deal_count)*12)}%`}}/></div><strong>{Number(s.total_amount).toLocaleString()}</strong></div>)}</div><div className="conversion-chart"><div className="panel-head"><h2>Lead conversion</h2><small>By current status</small></div>{data.lead_status_counts.map(x=><div className="conversion-row" key={x.status}><span>{x.status}</span><div className="bar"><i style={{width:`${Math.round(Number(x.total)/Math.max(1,...data.lead_status_counts.map(v=>Number(v.total)))*100)}%`}}/></div><strong>{x.total}</strong></div>)}</div></section><section className="panel"><div className="panel-head"><div><h2>Upcoming tasks</h2><p>Assigned to you</p></div><CheckSquare size={18}/></div>{data.upcoming_tasks.length?data.upcoming_tasks.map(t=><div className="task-row" key={t.id}><span className="task-dot"/><div><strong>{t.subject}</strong><small>{parseUtc(t.due_at).toLocaleString()}</small></div><span className="tag">{t.priority}</span></div>):<EmptyState title="No upcoming tasks" text="Your scheduled work will appear here."/>}</section></div></>}</>}
function Metric({label,value,hint,icon:Icon}){return <div className="metric-card"><div className="metric-top"><span>{label}</span><span className="metric-icon"><Icon size={18}/></span></div><strong>{value}</strong><small>{hint}</small></div>}
function ResourcePage({resource,onOpen}){const title=resource==='roles'?'Roles & Permissions':resource==='custom-fields'?'Custom Fields':resource.charAt(0).toUpperCase()+resource.slice(1).replaceAll('-',' ');return resource==='roles'?<RolesPage/>:resource==='teams'?<TeamsPage/>:<CrudPage resource={resource} title={title} onOpen={onOpen}/>}
function RolesPage(){const[roles,setRoles]=useState([]),[selected,setSelected]=useState(''),[data,setData]=useState(null),[error,setError]=useState(''),[saved,setSaved]=useState(false);useEffect(()=>{api('roles?per_page=100').then(r=>{setRoles(r.items||[]);if(r.items?.length)setSelected(String(r.items[0].id))}).catch(e=>setError(e.message))},[]);useEffect(()=>{if(selected)api(`roles/${selected}/permissions`).then(setData).catch(e=>setError(e.message))},[selected]);async function save(){try{await api(`roles/${selected}/permissions`,{method:'PUT',body:{permission_ids:data.permissions.filter(p=>p.enabled).map(p=>Number(p.id))}});setSaved(true);setTimeout(()=>setSaved(false),2200)}catch(e){setError(e.message)}}return <><PageHeading eyebrow="ADMINISTRATION" title="Roles & permissions" subtitle="Control which modules each workspace role can access." action={data&&<button className="primary" onClick={save}>Save permissions</button>}/><ErrorBanner error={error}/>{saved&&<div className="success-line"><Check size={16}/>Permissions saved.</div>}<div className="panel"><div className="table-toolbar"><label className="field"><span>Role</span><select value={selected} onChange={e=>setSelected(e.target.value)}>{roles.map(r=><option value={r.id} key={r.id}>{r.name}</option>)}</select></label></div>{data?<div className="permission-grid">{data.permissions.map(p=><label className="permission-item" key={p.id}><input type="checkbox" checked={!!Number(p.enabled)} onChange={e=>setData({...data,permissions:data.permissions.map(x=>x.id===p.id?{...x,enabled:e.target.checked}:x)})}/><span><strong>{p.label}</strong><small>{p.permission_key}</small></span></label>)}</div>:<Loading/>}</div></>}
