function CrudPage({resource,title,onOpen}){const cfg=config[resource]||config.leads,[items,setItems]=useState([]),[page,setPage]=useState(1),[total,setTotal]=useState(0),[q,setQ]=useState(''),[filter,setFilter]=useState(''),[sourceFilter,setSourceFilter]=useState(''),[scoreFilter,setScoreFilter]=useState(''),[ownerFilter,setOwnerFilter]=useState(''),[leadStats,setLeadStats]=useState(null),[busy,setBusy]=useState(true),[error,setError]=useState(''),[form,setForm]=useState(null),[saving,setSaving]=useState(false),[editing,setEditing]=useState(null),[lineItems,setLineItems]=useState([]),loc=useLocation();const apiName=cfg.api;const load=()=>{setBusy(true);const params={page,per_page:25,q:loc.search?new URLSearchParams(loc.search).get('q'):q};if(resource==='leads'&&filter==='unassigned')params.unassigned=1;else if(resource==='leads'&&filter)params.lead_status=filter;if(resource==='leads'&&sourceFilter)params.lead_source=sourceFilter;if(resource==='leads'&&scoreFilter)params.lead_score=scoreFilter;if(resource==='leads'&&ownerFilter)params.assigned_to=ownerFilter;api(`${apiName}?${query(params)}`).then(d=>{setItems(d.items||[]);setTotal(d.pagination?.total||0)}).catch(e=>setError(e.message)).finally(()=>setBusy(false))};useEffect(()=>{load();if(resource==='leads')api('dashboard').then(setLeadStats).catch(()=>{})},[resource,page,filter,sourceFilter,scoreFilter,ownerFilter,loc.search]);const start=(row=null)=>{setEditing(row);setForm(row?{...row}:{});setLineItems(['quotes','invoices'].includes(resource)?[{item_name:'',description:'',quantity:'1',unit_price:'',discount_amount:'0',discount_percent:'0',tax_rate:'0'}]:[]);};async function save(e){e.preventDefault();setSaving(true);setError('');try{let payload={...form};if(['quotes','invoices'].includes(resource)&&!editing){payload.items=lineItems;delete payload.item_name;delete payload.quantity;delete payload.unit_price;delete payload.tax_rate;}if(resource==='payments')await api(`invoices/${form.invoice_id}/payments`,{method:'POST',body:payload});else await api(`${apiName}${editing?'/'+editing.id:''}`,{method:editing?'PUT':'POST',body:payload});setForm(null);setEditing(null);setPage(1);load()}catch(e){setError(e.message)}finally{setSaving(false)}}async function remove(row){if(!confirm('Delete this record?'))return;try{await api(`${apiName}/${row.id}`,{method:'DELETE'});load()}catch(e){setError(e.message)}}return <><PageHeading eyebrow={resource==='support'?'CUSTOMER SERVICE':'WORKSPACE'} title={title} subtitle={`${total} record${total===1?'':'s'} in this workspace`} action={cfg.fields.length?<button className="primary" onClick={start}><Plus size={17}/> New {resource==='leads'?'lead':resource==='support'?'ticket':title.replace(/s$/,'')}</button>:null}/><ErrorBanner error={error}/>{resource==='leads'&&leadStats&&<div className="metric-grid lead-kpi"><Metric label="Total leads" value={leadStats.leads.total} hint="In this workspace" icon={Users}/><Metric label="New today" value={leadStats.leads.new_today} hint="Created since midnight" icon={CalendarDays}/><Metric label="Qualified rate" value={`${leadStats.leads.qualified_rate}%`} hint="Qualified leads" icon={Check}/><Metric label="Unassigned" value={leadStats.leads.unassigned} hint="Needs an owner" icon={UserRound}/></div>}<div className="panel table-panel"><div className="table-toolbar"><div className="table-search"><Search size={16}/><input placeholder={`Search ${title.toLowerCase()}…`} value={q} onChange={e=>{setQ(e.target.value);setPage(1)}} onKeyDown={e=>e.key==='Enter'&&load()}/></div>{resource==='leads'&&<select value={filter} onChange={e=>{setFilter(e.target.value);setPage(1)}}><option value="">All statuses</option><option value="unassigned">Unassigned queue</option>{['New','Contacted','Qualified','Unqualified','Lost'].map(x=><option key={x}>{x}</option>)}</select>}{resource==='leads'&&<><select value={sourceFilter} onChange={e=>{setSourceFilter(e.target.value);setPage(1)}}><option value="">All sources</option>{['Website Form','Referral','Cold Call','Paid Ad','Event'].map(x=><option key={x}>{x}</option>)}</select><input aria-label="Minimum lead score" type="number" min="1" max="100" placeholder="Score" value={scoreFilter} onChange={e=>setScoreFilter(e.target.value)}/><input aria-label="Assigned rep user ID" type="number" min="1" placeholder="Rep ID" value={ownerFilter} onChange={e=>setOwnerFilter(e.target.value)}/></>}<button className="subtle-button" onClick={load}>Refresh</button></div>{busy?<Loading/>:items.length?<div className="table-scroll"><table><thead><tr>{columns(resource,items).map(c=><th key={c}>{labelize(c)}</th>)}<th>Actions</th></tr></thead><tbody>{items.map(row=><tr key={row.id} onClick={()=>onOpen({type:'record',resource,row})}>{columns(resource,items).map(c=><td key={c}>{resource==='leads'&&c==='lead_status'?<select className="inline-select" value={row[c]} onClick={e=>e.stopPropagation()} onChange={async e=>{try{await api(`leads/${row.id}`,{method:'PATCH',body:{lead_status:e.target.value}});load()}catch(x){setError(x.message)}}}>{['New','Contacted','Qualified','Unqualified','Lost'].map(x=><option key={x}>{x}</option>)}</select>:formatCell(row[c])}</td>)}<td onClick={e=>e.stopPropagation()}><button className="row-action" onClick={()=>onOpen({type:'record',resource,row})}>Open</button><button className="row-action" onClick={()=>start(row)}>Edit</button>{resource==='leads'&&row.lead_status==='Qualified'&&!row.converted_deal_id&&<button className="row-action" onClick={async()=>{try{await api(`leads/${row.id}/convert`,{method:'POST',body:{}});load()}catch(x){setError(x.message)}}}>Convert</button>}{resource==='quotes'&&<><button className="row-action" onClick={()=>window.open(`${window.HA_CRM_BASE||''}/api/quotes/${row.id}/pdf`,'_blank')}>PDF</button><button className="row-action" onClick={async()=>{try{await api(`quotes/${row.id}/invoice`,{method:'POST',body:{}});load()}catch(x){setError(x.message)}}}>Invoice</button></>}{resource==='invoices'&&<><button className="row-action" onClick={()=>window.open(`${window.HA_CRM_BASE||''}/api/invoices/${row.id}/pdf`,'_blank')}>PDF</button>{row.status==='Draft'&&<button className="row-action" onClick={async()=>{try{await api(`invoices/${row.id}/send`,{method:'POST',body:{}});load()}catch(x){setError(x.message)}}}>Send</button>}</>}<button className="row-action danger-text" onClick={()=>remove(row)}>Delete</button></td></tr>)}</tbody></table></div>:<EmptyState title={`No ${title.toLowerCase()} yet`} text="Create a record to start working in this module."/>}<div className="pagination"><span>Page {page} · {total} records</span><div><button disabled={page<=1} onClick={()=>setPage(page-1)}>Previous</button><button disabled={page*25>=total} onClick={()=>setPage(page+1)}>Next</button></div></div></div>{form&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setForm(null)}><form className="modal" onSubmit={save}><div className="modal-head"><div><span className="eyebrow">NEW RECORD</span><h2>{editing?'Edit':'Create'} {title.slice(0,-1)}</h2></div><button type="button" className="icon-button" onClick={()=>setForm(null)}>×</button></div><div className="form-grid">{cfg.fields.map(([key,label,type='text',required=false,options=[]])=><Field key={key} label={label} name={key} type={type} required={required} value={form[key]??''} options={options} onChange={e=>setForm({...form,[key]:e.target.value})}/>)}</div>{['quotes','invoices'].includes(resource)&&!editing&&<section className="billing-line-editor"><div className="panel-head"><div><h3>Line items</h3><p>Totals are calculated and rounded by the server.</p></div><button type="button" className="secondary" onClick={()=>setLineItems([...lineItems,{item_name:'',description:'',quantity:'1',unit_price:'',discount_amount:'0',discount_percent:'0',tax_rate:'0'}])}>Add item</button></div>{lineItems.map((item,index)=><div className="billing-line-row" key={index}><Field label="Item name" name={`item_name_${index}`} required value={item.item_name} onChange={e=>setLineItems(lineItems.map((x,i)=>i===index?{...x,item_name:e.target.value}:x))}/><Field label="Description" name={`description_${index}`} type="textarea" value={item.description} onChange={e=>setLineItems(lineItems.map((x,i)=>i===index?{...x,description:e.target.value}:x))}/><Field label="Quantity" name={`quantity_${index}`} type="number" required value={item.quantity} min="0.001" step="0.001" onChange={e=>setLineItems(lineItems.map((x,i)=>i===index?{...x,quantity:e.target.value}:x))}/><Field label="Unit price" name={`unit_price_${index}`} type="number" required value={item.unit_price} min="0" step="0.01" onChange={e=>setLineItems(lineItems.map((x,i)=>i===index?{...x,unit_price:e.target.value}:x))}/><Field label="Discount amount" name={`discount_amount_${index}`} type="number" value={item.discount_amount} min="0" step="0.01" onChange={e=>setLineItems(lineItems.map((x,i)=>i===index?{...x,discount_amount:e.target.value}:x))}/><Field label="Discount %" name={`discount_percent_${index}`} type="number" value={item.discount_percent} min="0" max="100" step="0.01" onChange={e=>setLineItems(lineItems.map((x,i)=>i===index?{...x,discount_percent:e.target.value}:x))}/><Field label="Tax %" name={`tax_rate_${index}`} type="number" value={item.tax_rate} min="0" max="100" step="0.01" onChange={e=>setLineItems(lineItems.map((x,i)=>i===index?{...x,tax_rate:e.target.value}:x))}/>{lineItems.length>1&&<button type="button" className="row-action danger-text" onClick={()=>setLineItems(lineItems.filter((_,i)=>i!==index))}>Remove</button>}</div>)}</section>}<div className="modal-actions"><button type="button" className="secondary" onClick={()=>setForm(null)}>Cancel</button><button className="primary" disabled={saving}>{saving?'Saving…':editing?'Save changes':'Save record'}</button></div></form></div>}</>}
function columns(resource,items){if(resource==='leads')return ['first_name','last_name','email','company','lead_status','lead_source','priority'];if(resource==='deals')return ['deal_title','stage_id','amount','expected_close_date','assigned_to'];if(resource==='contacts')return ['first_name','last_name','email','phone','account_id'];if(resource==='accounts')return ['company_name','industry','phone','website'];if(resource==='activities')return ['subject','activity_type','due_at','status','priority','assigned_to'];if(resource==='quotes')return ['quote_number','issue_date','due_date','currency','grand_total','status'];if(resource==='invoices')return ['invoice_number','issue_date','due_date','currency','grand_total','paid_amount','balance_due','status'];if(resource==='payments')return ['invoice_id','amount','currency','payment_date','method','reference'];if(resource==='support')return ['ticket_number','subject','status','priority','assigned_to','sla_due_at'];if(resource==='users')return ['full_name','email','role','status'];if(resource==='teams')return ['name','created_at'];if(resource==='custom-fields')return ['entity_type','label','field_key','field_type','is_active'];return items[0]?Object.keys(items[0]).filter(k=>!['tenant_id','deleted_at','updated_at'].includes(k)).slice(0,6):['id'];}
function parseUtc(v){return new Date(`${String(v).replace(' ','T')}Z`)}function labelize(s){return s.replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase())}function formatCell(v){if(v===null||v===undefined||v==='')return '—';if(typeof v==='object')return JSON.stringify(v);return String(v)}
function Field({label,name,type='text',required=false,value,onChange,options=[],...props}){return <label className="field"><span>{label}{required&&<b> *</b>}</span>{type==='textarea'?<textarea name={name} value={value} onChange={onChange} required={required} rows="3" {...props}/>:type==='select'?<select name={name} value={value} onChange={onChange} required={required}><option value="">Select…</option>{options.map(o=><option key={o} value={o}>{o}</option>)}</select>:<input name={name} type={type} value={value} onChange={onChange} required={required} {...props}/>}</label>}
function Deals({onOpen}){const [deals,setDeals]=useState([]),[stages,setStages]=useState([]),[mode,setMode]=useState('board'),[error,setError]=useState('');const load=()=>Promise.all([api('deals?per_page=100'),api('pipeline-stages?per_page=100')]).then(([d,s])=>{setDeals(d.items);setStages(s.items)}).catch(e=>setError(e.message));useEffect(()=>{load()},[]);async function move(deal,stage){try{await api(`deals/${deal.id}/convert-stage`,{method:'POST',body:{stage_id:stage.id}});load()}catch(e){setError(e.message)}}return <><PageHeading eyebrow="SALES" title="Sales pipeline" subtitle={`${deals.length} deals · drag a card to move it between stages`} action={<div className="segmented"><button className={mode==='board'?'selected':''} onClick={()=>setMode('board')}>Kanban</button><button className={mode==='list'?'selected':''} onClick={()=>setMode('list')}>List</button></div>}/><ErrorBanner error={error}/>{mode==='board'?<div className="kanban">{stages.map(s=><div className="kanban-col" key={s.id} onDragOver={e=>e.preventDefault()} onDrop={e=>{const id=Number(e.dataTransfer.getData('deal-id'));const d=deals.find(x=>x.id===id);if(d)move(d,s)}}><div className="kanban-head"><div><strong>{s.name}</strong><small>{deals.filter(d=>Number(d.stage_id)===Number(s.id)).length} deals</small></div><span>{deals.filter(d=>Number(d.stage_id)===Number(s.id)).reduce((n,d)=>n+Number(d.amount||0),0).toLocaleString()}</span></div>{deals.filter(d=>Number(d.stage_id)===Number(s.id)).map(d=><article className="deal-card" key={d.id} onClick={()=>onOpen({type:"record",resource:"deals",row:d})} draggable onDragStart={e=>e.dataTransfer.setData('deal-id',d.id)}><strong>{d.deal_title}</strong>{d.company_name&&<small>{d.company_name}</small>}<small>{d.currency} {Number(d.amount).toLocaleString()}</small>{Number(d.overdue_task)>0&&<span className="overdue-flag">Overdue task</span>}<footer><span>{d.expected_close_date||'No close date'}</span><span className="avatar tiny">{String(d.assigned_to||'?').slice(0,1)}</span></footer></article>)}</div>)}</div>:<CrudPage resource="deals" title="Deals" onOpen={onOpen}/>}</>}
function Calendar(){const [items,setItems]=useState([]),[error,setError]=useState(''),[mode,setMode]=useState('month'),[current,setCurrent]=useState(new Date());useEffect(()=>{api('activities?per_page=100').then(d=>setItems(d.items)).catch(e=>setError(e.message))},[]);const clean=d=>parseUtc(d);const title=mode==='month'?current.toLocaleDateString(undefined,{month:'long',year:'numeric'}):mode==='day'?current.toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'}):`Week of ${current.toLocaleDateString(undefined,{month:'short',day:'numeric'})}`;function shift(delta){const d=new Date(current);if(mode==='month')d.setMonth(d.getMonth()+delta);else d.setDate(d.getDate()+delta*(mode==='week'?7:1));setCurrent(d)}function days(){let start=new Date(current);if(mode==='month'){start=new Date(current.getFullYear(),current.getMonth(),1);start.setDate(start.getDate()-((start.getDay()+6)%7));return Array.from({length:42},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);return d})}if(mode==='week'){start.setDate(start.getDate()-((start.getDay()+6)%7));return Array.from({length:7},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);return d})}return [new Date(current)]}const groups=['Overdue','Due Today','Upcoming','Completed'];function bucket(x){const t=clean(x.due_at),now=new Date();if(x.status==='Completed')return'Completed';if(t<now)return'Overdue';if(t.toDateString()===now.toDateString())return'Due Today';return'Upcoming'}return <><PageHeading eyebrow="WORK" title="Calendar & activities" subtitle="Monthly, weekly, and daily schedule with grouped task list." action={<button className="primary" onClick={()=>location.assign(`${window.HA_CRM_BASE||''}/activities`)}>Manage activities</button>}/><ErrorBanner error={error}/><div className="panel calendar-panel"><div className="calendar-controls"><div className="calendar-nav"><button onClick={()=>shift(-1)}>‹</button><button onClick={()=>setCurrent(new Date())}>Today</button><button onClick={()=>shift(1)}>›</button><strong>{title}</strong></div><div className="segmented">{['month','week','day','list'].map(m=><button className={mode===m?'selected':''} key={m} onClick={()=>setMode(m)}>{m[0].toUpperCase()+m.slice(1)}</button>)}</div></div>{mode==='list'?<div className="calendar-grid">{groups.map(g=><section className="panel" key={g}><div className="panel-head"><h2>{g}</h2><span className="tag">{items.filter(x=>bucket(x)===g).length}</span></div>{items.filter(x=>bucket(x)===g).map(x=><div className="task-row" key={x.id}><span className="task-dot"/><div><strong>{x.subject}</strong><small>{x.activity_type} · {clean(x.due_at).toLocaleString()}</small></div></div>)}</section>)}</div>:<div className={`calendar-days ${mode}`}><div className="week-labels">{(mode==='day'?[current.toLocaleDateString(undefined,{weekday:'short'})]:['Mon','Tue','Wed','Thu','Fri','Sat','Sun']).map((d,i)=><span key={i}>{d}</span>)}</div>{days().map((day,i)=><div className={`calendar-day ${day.getMonth()!==current.getMonth()&&mode==='month'?'outside':''} ${day.toDateString()===new Date().toDateString()?'today':''}`} key={i}><span className="day-num">{day.getDate()}</span>{items.filter(x=>clean(x.due_at).toDateString()===day.toDateString()).map(x=><div className="calendar-event" key={x.id} title={x.subject}>{clean(x.due_at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})} {x.subject}</div>)}</div>)}</div>}</div></>}
function Reports(){const [kind,setKind]=useState('forecast'),[data,setData]=useState([]),[error,setError]=useState('');useEffect(()=>{api(`reports/${kind}`).then(setData).catch(e=>setError(e.message))},[kind]);const valueKey=kind==='forecast'?'forecast_amount':kind==='performance'?'won_amount':'won_revenue';const max=Math.max(1,...data.map(x=>Number(x[valueKey]||0)));return <><PageHeading eyebrow="INSIGHTS" title="Reports & analytics" subtitle="Tenant-scoped sales performance and revenue metrics." action={<select value={kind} onChange={e=>setKind(e.target.value)}><option value="forecast">Revenue forecast</option><option value="performance">Agent performance</option><option value="sources">Lead source ROI</option></select>}/><ErrorBanner error={error}/>{data.length>0&&<div className="panel report-chart">{data.map((row,i)=><div className="report-bar-row" key={i}><span>{row.stage||row.full_name||row.source||'Other'}</span><div className="bar"><i style={{width:`${Math.round(Number(row[valueKey]||0)/max*100)}%`}}/></div><strong>{Number(row[valueKey]||0).toLocaleString()}</strong></div>)}</div>}<div className="panel table-panel"><div className="table-scroll"><table><thead><tr>{data[0]&&Object.keys(data[0]).map(k=><th key={k}>{labelize(k)}</th>)}</tr></thead><tbody>{data.map((row,i)=><tr key={i}>{Object.values(row).map((v,j)=><td key={j}>{formatCell(v)}</td>)}</tr>)}</tbody></table></div>{!data.length&&<EmptyState title="No report data yet" text="Results will appear once your workspace has records."/>}</div></>}
function TeamsPage(){const[teams,setTeams]=useState([]),[members,setMembers]=useState([]),[users,setUsers]=useState([]),[name,setName]=useState(''),[teamId,setTeamId]=useState(''),[userId,setUserId]=useState(''),[error,setError]=useState('');const load=()=>Promise.all([api('teams?per_page=100'),api('team-members?per_page=100'),api('users?per_page=100')]).then(([t,m,u])=>{setTeams(t.items||[]);setMembers(m.items||[]);setUsers(u.items||[]);if(!teamId&&t.items?.length)setTeamId(String(t.items[0].id))}).catch(e=>setError(e.message));useEffect(()=>{load()},[]);async function createTeam(e){e.preventDefault();try{await api('teams',{method:'POST',body:{name}});setName('');load()}catch(e){setError(e.message)}}async function addMember(e){e.preventDefault();try{await api('team-members',{method:'POST',body:{team_id:Number(teamId),user_id:Number(userId)}});setUserId('');load()}catch(e){setError(e.message)}}async function removeMember(id){try{await api(`team-members/${id}`,{method:'DELETE'});load()}catch(e){setError(e.message)}}return <><PageHeading eyebrow="ADMINISTRATION" title="Teams" subtitle="Create teams and manage tenant users’ team membership."/><ErrorBanner error={error}/><div className="content-grid"><form className="panel settings-form" onSubmit={createTeam}><h2>Create a team</h2><Field label="Team name" name="team_name" required value={name} onChange={e=>setName(e.target.value)}/><button className="primary">Add team</button><div className="team-list">{teams.map(t=><button type="button" className={`team-choice ${String(t.id)===teamId?'selected':''}`} key={t.id} onClick={()=>setTeamId(String(t.id))}>{t.name}</button>)}</div></form><form className="panel settings-form" onSubmit={addMember}><h2>Team members</h2><label className="field"><span>Team</span><select value={teamId} onChange={e=>setTeamId(e.target.value)} required>{teams.map(t=><option key={t.id} value={t.id}>{t.name}</option>)}</select></label><label className="field"><span>User</span><select value={userId} onChange={e=>setUserId(e.target.value)} required><option value="">Select a user…</option>{users.filter(u=>!members.some(m=>Number(m.team_id)===Number(teamId)&&Number(m.user_id)===Number(u.id))).map(u=><option key={u.id} value={u.id}>{u.full_name} · {u.role}</option>)}</select></label><button className="primary" disabled={!teams.length}>Add member</button><div className="team-member-list">{members.filter(m=>Number(m.team_id)===Number(teamId)).map(m=><div className="task-row" key={m.id}><div><strong>{users.find(u=>Number(u.id)===Number(m.user_id))?.full_name||`User ${m.user_id}`}</strong><small>{users.find(u=>Number(u.id)===Number(m.user_id))?.role||''}</small></div><button type="button" className="row-action danger-text" onClick={()=>removeMember(m.id)}>Remove</button></div>)}</div></form></div></>}function SettingsPage(){const [settings,setSettings]=useState({}),[smtp,setSmtp]=useState({}),[error,setError]=useState(''),[saved,setSaved]=useState('');useEffect(()=>{api('company-settings').then(setSettings).catch(()=>{});api('smtp').then(setSmtp).catch(()=>{})},[]);async function saveCompany(e){e.preventDefault();try{await api('company-settings',{method:'PUT',body:settings});setSaved('Company details saved.')}catch(x){setError(x.message)}}async function saveSmtp(e){e.preventDefault();try{const r=await api('smtp',{method:'PUT',body:smtp});setSmtp({...smtp,is_configured:r.is_configured,password:''});setSaved('SMTP configuration saved.')}catch(x){setError(x.message)}}return <><PageHeading eyebrow="ADMINISTRATION" title="Settings" subtitle="Workspace profile and email delivery configuration."/><ErrorBanner error={error}/>{saved&&<div className="success-line"><Check size={16}/>{saved}</div>}<div className="settings-grid"><form className="panel settings-form" onSubmit={saveCompany}><h2>Company settings</h2>{[['company_name','Company name'],['registration_number','Registration number'],['tax_id','Tax ID'],['phone','Phone'],['website','Website'],['address','Office address']].map(([k,l])=><Field key={k} label={l} name={k} value={settings[k]||''} onChange={e=>setSettings({...settings,[k]:e.target.value})} type={k==='address'?'textarea':'text'}/>)}<button className="primary">Save company</button></form><form className="panel settings-form" onSubmit={saveSmtp}><h2>Email / SMTP</h2><p className="muted">Status: {smtp.is_configured?'Configured':'Not configured'}</p>{[['host','SMTP host'],['port','Port'],['username','Username'],['password','SMTP password'],['from_email','From email'],['from_name','From name']].map(([k,l])=><Field key={k} label={l} name={k} type={k==='password'?'password':k==='port'?'number':k==='from_email'?'email':'text'} value={smtp[k]||''} onChange={e=>setSmtp({...smtp,[k]:e.target.value})}/>)}<label className="field"><span>Encryption</span><select value={smtp.encryption||'tls'} onChange={e=>setSmtp({...smtp,encryption:e.target.value})}><option value="tls">TLS</option><option value="ssl">SSL</option><option value="none">None</option></select></label><button className="primary">Save SMTP settings</button></form></div></>}
function ContextDrawer({value,close}){const record=value.row||{};return <><div className="drawer-scrim" onClick={close}/><aside className="context-drawer"><div className="drawer-head"><div><span className="eyebrow">{value.type==='notifications'?'INBOX':labelize(value.resource)}</span><h2>{value.type==='notifications'?'Notifications':record.deal_title||record.company_name||record.subject||`${record.first_name||''} ${record.last_name||''}`||'Record details'}</h2></div><button className="icon-button" onClick={close}>×</button></div>{value.type==='notifications'?<NotificationList/>:<><div className="detail-list">{Object.entries(record).filter(([k])=>!['tenant_id','password_hash'].includes(k)).map(([k,v])=><div key={k}><small>{labelize(k)}</small><span>{formatCell(v)}</span></div>)}</div>{value.resource==='contacts'&&<Timeline type="contact" id={record.id}/>}{value.resource==='accounts'&&<Timeline type="account" id={record.id}/>}{value.resource==='support'&&<TicketConversation id={record.id}/>}{['quotes','invoices'].includes(value.resource)&&<DocumentItems type={value.resource} id={record.id}/>}{['leads','contacts','accounts','deals','support'].includes(value.resource)&&<CustomFields entity={value.resource==='support'?'tickets':value.resource} id={record.id}/>}</>}</aside></>}
function DocumentItems({type,id}){const[items,setItems]=useState([]);useEffect(()=>{const key=type==='quotes'?'quote_id':'invoice_id';api(`${type==='quotes'?'quote-items':'invoice-items'}?${key}=${id}`).then(x=>setItems(x.items||[])).catch(()=>{})},[type,id]);return <section className="drawer-section"><h3>Line items</h3>{items.map(x=><div className="task-row" key={x.id}><div><strong>{x.item_name}</strong><small>{x.quantity} × {x.unit_price} · Tax {x.tax_rate}%</small></div><span>{x.item_total}</span></div>)}</section>}function NotificationList(){const[rows,setRows]=useState([]);useEffect(()=>{api('notifications/poll?since=0').then(setRows).catch(()=>{})},[]);async function markRead(n){if(n.read_at)return;try{await api('notifications/read',{method:'POST',body:{id:n.id}});setRows(rows.map(x=>x.id===n.id?{...x,read_at:new Date().toISOString()}:x))}catch{}}async function markAll(){try{await api('notifications/read',{method:'POST',body:{}});setRows(rows.map(x=>({...x,read_at:x.read_at||new Date().toISOString()})))}catch{}}return <>{'Notification'in window&&<button className="subtle-button" onClick={()=>window.Notification.requestPermission()}>Enable desktop alerts</button>}{rows.some(n=>!n.read_at)&&<button className="subtle-button" onClick={markAll}>Mark all read</button>}{rows.length?rows.map(n=><div role="button" tabIndex="0" className={`notification-row ${n.read_at?'read':''}`} key={n.id} onClick={()=>markRead(n)} onKeyDown={e=>e.key==='Enter'&&markRead(n)}><strong>{n.title}</strong><p>{n.body}</p><small>{new Date(n.created_at).toLocaleString()}</small></div>):<EmptyState title="You’re all caught up" text="New task and CRM notifications will show here."/>}</>}function Timeline({type,id}){const[events,setEvents]=useState([]);useEffect(()=>{if(id)api(`timeline/${type}/${id}`).then(setEvents).catch(()=>{})},[type,id]);return <section className="drawer-section"><h3>Interaction timeline</h3>{events.map(e=><div className="timeline-event" key={`${e.type}-${e.id}`}><span className={`timeline-dot ${e.type}`}/><div><strong>{e.title}</strong><small>{e.type} · {e.detail} · {e.happened_at}</small></div></div>)}{!events.length&&<small className="muted">No linked activity yet.</small>}</section>}
function CustomFields({entity,id}){const[defs,setDefs]=useState([]),[values,setValues]=useState({}),[error,setError]=useState('');useEffect(()=>{if(!id)return;Promise.all([api(`custom-fields?entity_type=${entity}&per_page=100`),api(`custom-field-values?entity_type=${entity}&entity_id=${id}&per_page=100`)]).then(([d,v])=>{setDefs(d.items||[]);setValues(Object.fromEntries((v.items||[]).map(x=>[x.definition_id,x])))}).catch(()=>{})},[entity,id]);async function save(def,value){try{const old=values[def.id];if(old)await api(`custom-field-values/${old.id}`,{method:'PUT',body:{value_text:value}});else{const result=await api('custom-field-values',{method:'POST',body:{definition_id:def.id,entity_type:entity,entity_id:id,value_text:value}});setValues({...values,[def.id]:{id:result.id,definition_id:def.id,value_text:value}})}}catch(e){setError(e.message)}}if(!defs.length)return null;return <section className="drawer-section"><h3>Custom fields</h3>{error&&<small className="danger-text">{error}</small>}{defs.map(d=><label className="field" key={d.id}><span>{d.label}</span><input defaultValue={values[d.id]?.value_text||''} onBlur={e=>save(d,e.target.value)} type={d.field_type==='number'?'number':d.field_type==='date'?'date':d.field_type==='email'?'email':d.field_type==='url'?'url':'text'}/></label>)}</section>}
function TicketConversation({id}){const[mode,setMode]=useState('reply'),[rows,setRows]=useState([]),[text,setText]=useState(''),[error,setError]=useState('');const load=()=>Promise.all([api(`ticket-messages?ticket_id=${id}&per_page=100`),api(`ticket-notes?ticket_id=${id}&per_page=100`)]).then(([m,n])=>setRows([...m.items.map(x=>({...x,kind:'reply'})),...n.items.map(x=>({...x,kind:'note'}))].sort((a,b)=>a.id-b.id))).catch(e=>setError(e.message));useEffect(()=>{load()},[id]);async function submit(e){e.preventDefault();try{await api(mode==='reply'?'ticket-messages':'ticket-notes',{method:'POST',body:mode==='reply'?{ticket_id:id,message:text}:{ticket_id:id,note:text}});setText('');load()}catch(e){setError(e.message)}}return <section className="drawer-section"><h3>Ticket conversation</h3><div className="segmented"><button className={mode==='reply'?'selected':''} onClick={()=>setMode('reply')}>Response</button><button className={mode==='note'?'selected':''} onClick={()=>setMode('note')}>Internal note</button></div>{error&&<small className="danger-text">{error}</small>}{rows.map(r=><div className={`ticket-message ${r.kind}`} key={`${r.kind}-${r.id}`}><small>{r.kind==='note'?'Internal note':'Agent response'}</small><p>{r.message||r.note}</p></div>)}<form onSubmit={submit}><label className="field"><span>{mode==='reply'?'Customer response':'Internal note'}</span><textarea value={text} onChange={e=>setText(e.target.value)} required rows="3"/></label><button className="primary">Save {mode==='reply'?'response':'note'}</button></form></section>}
function Loading(){return <div className="loading"><LoaderCircle className="spin" size={19}/> Loading records…</div>}function EmptyState({title,text}){return <div className="empty"><span className="empty-icon"><Search size={18}/></span><strong>{title}</strong><p>{text}</p></div>}function ErrorBanner({error}){return error?<div className="error-line"><AlertCircle size={16}/>{error}</div>:null}function NotFound(){return <div className="panel"><h2>Page not found</h2><p>The requested module does not exist.</p></div>}
createRoot(document.getElementById('root')).render(<React.StrictMode><App/></React.StrictMode>);
